# Compute distance from nearest edge for each cell of each color
def compute_edge_distances(grid, color):
    h, w = grid.shape
    mask = (grid == color)
    if not np.any(mask):
        return {}

    positions = np.argwhere(mask)
    distances = {}
    for pos in positions:
        r, c = pos
        dist = min(r, h-1-r, c, w-1-c)
        if dist not in distances:
            distances[dist] = len([p for p in positions if _dist(p, h, w) == dist])
    return distances

def _dist(pos, h, w):
    r, c = pos
    return min(r, h-1-r, c, w-1-c)

# Demo
